import React from 'react';

import { _useInformationOverlayContext } from './hooks/useInformationOverlayContext.js';
import type { DOMProps } from '../../core/types/dom.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { Paragraph } from '../../typography/Paragraph.js';
import { Text } from '../../typography/Text.js';

//#region Typings
// eslint-disable-next-line @typescript-eslint/no-empty-interface
export interface InformationContentProps extends DOMProps, WithChildren {}
//#endregion Typings

/** The content of the InformationOverlay. */
export const Content = ({ children, id: propId }: InformationContentProps) => {
  const { id } = _useInformationOverlayContext();

  if (typeof children === 'string') {
    return <Paragraph id={propId ?? id}>{children}</Paragraph>;
  }
  return (
    <Text as="div" textStyle="base" id={propId ?? id}>
      {children}
    </Text>
  );
};

Content['displayName'] = 'InformationOverlay.Content';
